CREATE TABLE celebration (id uuid PRIMARY KEY, slug text UNIQUE NOT NULL, organization_id uuid NULL, owner_id uuid NOT NULL, event_type_code text NOT NULL, status text NOT NULL CHECK (status IN ('DRAFT','PUBLISHED','ARCHIVED')), version integer NOT NULL DEFAULT 1, default_locale text NOT NULL DEFAULT 'es-BO', time_zone text NOT NULL DEFAULT 'America/La_Paz', currency char(3) NOT NULL DEFAULT 'BOB', content jsonb NOT NULL DEFAULT '{}', translations jsonb NOT NULL DEFAULT '{}', settings jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE event_type_definition (code text PRIMARY KEY, default_locale text NOT NULL, host_roles jsonb NOT NULL, enabled_sections jsonb NOT NULL, required_fields_for_publish jsonb NOT NULL, compatible_template_tags jsonb NOT NULL, translations jsonb NOT NULL);
CREATE TABLE read_public_celebration (slug text PRIMARY KEY, payload jsonb NOT NULL, projection_version integer NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE celebration ENABLE ROW LEVEL SECURITY;
CREATE POLICY celebration_tenant_policy ON celebration USING (id = current_setting('app.celebration_id', true)::uuid);
